const $ = (selector, root = document) => root.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const main = $('#main');
const dialog = $('#detail-dialog');
const content = $('#dialog-content');
let data, glossary, models, beginner = false, category = 'All', signal = 'all', query = '', year = 'all', returnDialog = null, selectedStage = 3, selectedCompany = 'openai', selectedIncident = 'hugging-face';
const expandedCompanies = new Set();
try { beginner = localStorage.getItem('frontier-simplified-vocabulary') === 'true'; } catch {}
const categories = ['All', 'Incidents', 'Capabilities', 'Governance', 'AI R&D', 'Cyber', 'Monitoring', 'Model proliferation', 'CBRN'];
const direction = {worsening:['↗','More concerning','amber'],improving:['↘','Safety signal','mint'],mixed:['↔','Mixed signal','muted']};
const date = value => new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));
function rich(text) { return escape(text).replace(/\[\[([^\]]+)\]\]/g,(_,term)=>`<button class="jargon" data-term="${escape(term.toLowerCase())}" aria-label="Define ${escape(term)}">${term}<span aria-hidden="true">ⓘ</span></button>`); }
function sources(event) { return event.sources.map(s=>`<a class="source-link" href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.publisher)} <span>↗</span><small>${escape(s.title)}</small></a>`).join(''); }
function openDialog(html) { content.innerHTML=html; if(!dialog.open) dialog.showModal(); dialog.scrollTop=0; $('.close-dialog').focus(); }
function reviewLabel(item) { if(item?.review?.status==='automated')return `Weekly automated summary · sources checked ${date(item.review.checkedAt)} · no human sign-off claimed.`; return item?.review?.status==='approved' ? `Reviewed by ${escape(item.review.reviewedBy)} on ${escape(item.review.reviewedAt)}.` : 'Imported summary · human editorial review pending.'; }
function sourceRange() { const dates=data.events.map(e=>e.date).sort(); const fmt=v=>new Intl.DateTimeFormat('en-US',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v+'T12:00:00Z'));return `${fmt(dates[0])}–${fmt(dates.at(-1))}`; }
function showEvent(id, worry = false) {
 const e=data.events.find(x=>x.id===id); if(!e)return;
 const d=direction[e.direction];
 openDialog(`<p class="eyebrow">${date(e.date)} · ${escape(e.category)} · ${e.kind==='background'?'HISTORICAL BACKGROUND':escape(e.kind.toUpperCase())}</p><h2 id="dialog-title">${escape(e.title)}</h2><div class="event-meta"><span class="${d[2]}">${d[0]} ${d[1]}</span><span>${escape(e.evidence)}</span></div><p class="event-dates"><strong>${escape(e.dateBasis)}:</strong> ${date(e.date)}<br><strong>Occurred:</strong> ${escape(e.occurred)}</p><p class="lead">${rich(beginner?e.summary_beginner:e.technical_summary)}</p><div class="interpretation"><section><p class="eyebrow">WHAT HAPPENED</p><p>${rich(e.summary_beginner)}</p></section><section><p class="eyebrow">WHAT IT MEANS <span class="small-note">/ INTERPRETATION</span></p><p>${rich(e.why_it_matters)}</p></section><section class="limit"><p class="eyebrow">WHAT IT DOESN’T MEAN</p><p>${rich(e.what_it_doesnt_mean)}</p></section><section><p class="eyebrow">WHAT WOULD RAISE CONCERN</p><p>${rich(e.what_would_raise_concern)}</p></section></div><details class="technical"><summary>Technical explanation</summary><p>${rich(e.technical_summary)}</p><p class="small-note">${escape(e.evidenceNote)}</p></details><details class="worry" ${worry?'open':''}><summary>How worried should I actually be? <span>+</span></summary><div class="worry-content"><h3 class="amber">More concerning because</h3><p>${rich(e.why_it_matters)}</p><h3 class="mint">Less concerning because</h3><p>${rich(e.less_concerning)}</p><h3>Still not established by this report</h3><p>Durable independent resource control, persistent self-replication, or successful resistance to a determined human shutdown.</p><div class="takeaway">${rich(e.conclusion)}</div></div></details><h3>Sources</h3><p class="small-note">${escape(e.evidenceNote)}</p>${sources(e)}<p class="small-note">${reviewLabel(e)} ${e.chatMessages.length?'Included from the <a href="#coverage" data-close>shared watch</a>.':''}</p>`);
 if(worry)$('.worry',content).scrollIntoView({block:'start',behavior:'instant'});
}
function showPathway(id) {
 const p=data.pathways.find(x=>x.id===id);if(!p)return;
 const events=data.events.filter(e=>p.eventIds.includes(e.id));
 openDialog(`<p class="eyebrow">RISK PATHWAY · EVIDENCE SUMMARY</p><h2 id="dialog-title">${escape(p.name)}</h2><p class="lead">${escape(p.question)}</p><span class="pill amber">${escape(p.status)} ${escape(p.trend)}</span><h3>What this means</h3><p>${rich(p.meaning)}</p><h3>Why it matters</h3><p>${rich(p.care)}</p><div class="limit standalone"><p class="eyebrow">WHAT HAS NOT BEEN ESTABLISHED</p><p>${rich(p.notDemonstrated)}</p></div><h3>Relevant evidence</h3>${events.map(e=>`<button class="related" data-event="${e.id}"><span><small>${date(e.date)}</small>${escape(e.title)}</span><span>↗</span></button>`).join('')}<h3>Direction to watch</h3><p>${escape(p.interpretation)} This is a qualitative reading of the selected sources, not a complete assessment of the field.</p>`);
}
function showOutlook() {
 const o=data.outlook;
 openDialog(`<p class="eyebrow">ASSESSMENT TRANSPARENCY · SOURCE-BASED SUMMARY</p><h2 id="dialog-title">Evidence behind this summary</h2><p>${escape(o.summary)}</p><h3>Supporting evidence</h3>${data.events.filter(e=>o.basis.includes(e.id)).map(e=>`<button class="related" data-event="${e.id}"><span><small>${escape(e.evidence)}</small>${escape(e.title)}</span><span>↗</span></button>`).join('')}<h3 class="amber">What would make the outlook worse?</h3><p>${escape(o.moreConcerning)}</p><h3 class="mint">What would make it better?</h3><p>${escape(o.lessConcerning)}</p><h3>What remains uncertain?</h3><p>How test results transfer to everyday use, how reliably safeguards hold up, and how capability changes interact. We do not convert these uncertainties into a precise catastrophe probability.</p><a class="text-link" href="#methodology" data-close>Methodology ↗</a>`);
}
function showTerm(term) {
 const g=glossary[term];if(!g)return;
 if(dialog.open && !returnDialog) returnDialog=content.innerHTML;
 openDialog(`<p class="eyebrow">GLOSSARY</p><h2 id="dialog-title">${escape(term.charAt(0).toUpperCase()+term.slice(1))}</h2><p class="lead">${escape(g.definition)}</p><h3>Think of it like…</h3><p>${escape(g.analogy)}</p>${returnDialog?'<button class="text-link" data-action="back-dialog">← Back to the evidence</button>':''}`);
}
function heading(title){return `<section class="page-heading"><h1>${title}</h1></section>`;}
function demoNote(){return `<div class="demo-note"><span class="demo-label">${data.updates?.enabled?'WEEKLY WATCH':'CHAT IMPORT'}</span><span>Coverage through ${date(data.asOf)}${data.updates?.enabled?` · ${escape(data.updates.scheduleLabel)}`:` · Source dates: ${sourceRange()}`}</span><a class="text-link" href="#coverage">Coverage ↗</a></div>`;}
function pathwayCards(){return data.pathways.map((p,i)=>`<button class="pathway-card" data-pathway="${p.id}"><span class="card-top"><span class="card-number">0${i+1}</span><span class="pathway-status">${escape(p.status)} ${escape(p.trend)}</span></span><h3>${escape(p.name)}</h3><p>${escape(p.question)}</p><span class="card-bottom">${escape(p.interpretation)}<span>↗</span></span></button>`).join('');}
function eventRows(events){return events.map(e=>{const d=direction[e.direction];return `<article class="event-row"><div class="event-date"><span>${new Date(e.date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})}</span><strong>${e.date.slice(8)}</strong><small>${e.date.slice(0,4)}</small></div><div class="event-body"><div class="event-meta"><span class="${d[2]}">${d[0]} ${d[1]}</span><span>${escape(e.category)}</span><span>${escape(e.evidence)}</span></div><h3><button data-event="${e.id}">${escape(e.title)}</button></h3><p>${rich(beginner?e.summary_beginner:e.technical_summary)}</p><p class="small-note occurrence">Occurred: ${escape(e.occurred)}</p><div class="event-bottom"><div>${e.pathways.map(id=>`<button class="tag" data-pathway="${id}">${escape(data.pathways.find(p=>p.id===id).name)}</button>`).join('')}</div><button class="worry-link" data-worry="${e.id}">How worried should I be? <span>↗</span></button></div></div></article>`;}).join('');}
function timelineMarkup(){return `<section id="timeline"><div class="section-head view-heading"><div><h1>Timeline</h1></div><span class="small-note">${data.events.length} records · ordered by report date</span></div><div class="timeline-search"><label for="event-search">Search records<input id="event-search" type="search" placeholder="Medicare, DNS, Hugging Face…" value="${escape(query)}"></label><label for="year-filter">Report year<select id="year-filter"><option value="all">All years</option>${[...new Set(data.events.map(e=>e.date.slice(0,4)))].sort().reverse().map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="timeline-controls"><div class="filters" role="group" aria-label="Filter notes by category">${categories.map(c=>`<button class="filter ${c===category?'selected':''}" data-filter="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div class="signal-filter"><label for="signal-filter">Signal direction</label><select id="signal-filter"><option value="all">All signals</option><option value="worsening">Capability & risk</option><option value="improving">Safety & control</option><option value="mixed">Mixed signals</option></select></div></div><p id="result-count" class="small-note" role="status" aria-live="polite"></p><div id="event-list"></div></section>`;}
const stages=[
 ['Tool use','Documented','An AI uses tools such as search, code execution, or external services.','Tool permissions connect model decisions to real effects.','dns-escape'],
 ['Autonomous multi-step work','Documented','An agent carries out several actions toward a task without approval at each step.','Research tasks and unauthorized coordination show why the full action sequence matters.','hugging-face'],
 ['Circumvents obstacles','Documented','An agent finds alternative routes after its approved approach fails.','A workaround can cross an authorization boundary even when the original goal is benign.','dns-escape'],
 ['Crosses intended boundaries','Documented','A system reaches information or services outside its authorized scope.','The records include both misconfigured evaluations and bypasses of intended restrictions.','medicare'],
 ['Acquires outside resources','Limited examples; attribution varies','Reports describe outside accounts, credentials, and services.','Limited resource access does not establish major compute ownership, capital control, or independence.','transluce-accounts'],
 ['Establishes external persistence','Not established by these records','An agent maintains an independent operating foothold beyond its original environment.','Stored files, public traces, or a temporary connection do not establish durable autonomous operation.',null],
 ['Replicates independently','Not established by these records','An agent creates and operates a functioning copy without a human carrying out the critical steps.','Neither a public upload nor multiple centrally launched agents establishes independent replication.',null],
 ['Resists human shutdown','Not established by these records','A system survives a determined, technically capable effort to stop it.','The DNS incident involved failed automated stopping followed by a successful human stop.','dns-escape'],
 ['Strategically improves itself','Not established by these records','An AI independently directs sustained cycles of improvement to its own capabilities.','Supervised AI-led research is relevant progress, but does not establish a fully autonomous improvement loop.','anthropic-rd-metrics']
];
function ladderMarkup(){return `<section id="ladder"><div class="section-head view-heading"><div><h1>Concern ladder</h1></div><span class="small-note">Capability levels, not a forecast.</span></div><div class="ladder-layout"><div class="ladder-steps" role="group" aria-label="Levels of agent capability">${stages.map((s,i)=>`<button class="ladder-step ${i===1?'selected':''} ${i>4?'unestablished':''}" data-stage="${i}" aria-pressed="${i===1}"><span class="step-number">${i+1<10?'0':''}${i+1}</span><span>${s[0]}</span><span class="step-status">${i<4?'●':i===4?'◐':'○'}</span></button>`).join('')}</div><div id="stage-detail" class="stage-detail" aria-live="polite"></div></div><p class="small-note ladder-note">Evidence labels refer to the records in this edition, with each source’s limitations. “Not established” does not mean impossible or disproven. These stages need not occur in order.</p></section>`;}
function renderStage(index){const s=stages[index];if(!s)return;selectedStage=index;document.querySelectorAll('[data-stage]').forEach(b=>{const selected=Number(b.dataset.stage)===index;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected);});$('#stage-detail').innerHTML=`<span class="stage-big">${String(index+1).padStart(2,'0')}</span><p class="eyebrow">${s[1]}</p><h3>${s[0]}</h3><p>${s[2]}</p><div class="stage-why"><p class="eyebrow">IMPLICATIONS</p><p>${s[3]}</p></div>${s[4]?`<button class="text-link" data-event="${s[4]}">Related research ↗</button>`:'<p class="small-note">No supporting event is established by these records.</p>'}`;}
function renderEvidence(){return `<section class="evidence-board"><div class="section-head"><div><h2>Evidence and interpretation</h2></div></div><div class="evidence-grid"><article><span class="evidence-label mint">01 / OBSERVED</span><p>Reports document unauthorized access, external communication, and a gap between detection and stopping.</p><button class="text-link" data-event="dns-escape">Incident report ↗</button></article><article><span class="evidence-label amber">02 / INFERRED</span><p>More capable agents need stronger access limits and monitoring. This is a judgment based on the evidence.</p><a class="text-link" href="#methodology">Methodology ↗</a></article><article><span class="evidence-label muted">03 / SPECULATIVE</span><p>A system could one day operate indefinitely beyond human control. These sources do not establish that outcome.</p><button class="text-link" data-action="future-stage">Shutdown resistance ↗</button></article></div></section>`;}
function overview(){const o=data.outlook;main.innerHTML=heading('AI risk overview')+demoNote()+`<section class="outlook"><div class="outlook-main"><p class="eyebrow">EVIDENCE SUMMARY</p><div class="risk-title"><h2>${escape(o.title||o.level)}</h2><span class="trend">↗ ${escape(o.trend)}</span></div><p>${escape(o.summary)}</p><button class="text-link" data-action="outlook">View supporting evidence <span>↗</span></button></div><aside class="outlook-aside"><span class="eyebrow">SIGNAL DIRECTION</span><button class="signal-row" data-signal="worsening"><span class="signal-symbol amber">↗</span><span><strong>Capability & risk</strong></span></button><button class="signal-row" data-signal="improving"><span class="signal-symbol mint">↘</span><span><strong>Safety & control</strong></span></button><div class="outlook-foot"><span class="small-note">No numeric risk score.<br>Human review pending.</span><a href="#methodology">How we assess ↗</a></div></aside></section><div class="changed-strip"><span class="eyebrow">LATEST NOTE</span><span>${escape(o.changed)}</span><button data-event="${data.latestEventId}" aria-label="Read latest incident note">↗</button></div><section id="pathways"><div class="section-head"><div><h2>Risk pathways</h2></div></div><div class="pathway-grid">${pathwayCards()}</div></section>`+renderEvidence();
}
function filterEvents(){const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean);const matches=data.events.filter(e=>(category==='All'||e.category===category)&&(signal==='all'||e.direction===signal)&&(year==='all'||e.date.startsWith(year))&&words.every(w=>[e.title,e.summary_beginner,e.technical_summary,e.occurred,e.evidence,...e.sources.map(s=>s.publisher)].join(' ').toLowerCase().includes(w)));$('#event-list').innerHTML=matches.length?eventRows(matches):`<div class="empty-state"><h3>No records match.</h3><button class="text-link" data-action="reset-filters">Show all records ↗</button></div>`;$('#result-count').textContent=`${matches.length} of ${data.events.length} records · Reports include incidents, research, policy, and follow-ups; this is not an incident count.`;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===category);b.setAttribute('aria-pressed',b.dataset.filter===category);});}
function coverageMarkup(){return `<section id="coverage"><h2>Conversation coverage</h2><p>Imported on ${date(data.importedAt)} from <a href="${escape(data.chatSource)}" target="_blank" rel="noopener noreferrer">Frontier AI Risk Watch ↗</a>. The original chat covers developments through ${date(data.chatAsOf||data.asOf)}. Later product discussions are included in the reconciliation below.</p><p>${data.events.filter(e=>e.chatMessages.length).length} records are linked to the conversation or its cited reports. ${data.events.filter(e=>!e.chatMessages.length&&e.review.status==='imported').length} earlier research notes remain as additional background. Repeated mentions link to the same record; grouped cases are described in their details.</p>${data.coverage.map(c=>`<details class="coverage-group"><summary>${date(c.date)} · ${c.eventIds.length} linked records${[64,88].includes(c.messageIndex)?' · product discussion':''}</summary><p class="small-note">${escape(c.note)}</p>${c.eventIds.map(id=>{const e=data.events.find(x=>x.id===id);return `<button class="related" data-event="${e.id}"><span>${escape(e.title)}</span><span>↗</span></button>`;}).join('')}</details>`).join('')}<h3>Corrections and counting rules</h3><ul>${data.corrections.map(c=>`<li>${escape(c)}</li>`).join('')}</ul></section>`;}
function updateHistoryMarkup(){const runs=data.updates?.history||[];return `<section id="weekly-updates"><h2>Weekly updates</h2>${runs.length?runs.slice().reverse().slice(0,12).map(r=>`<div class="source-record"><h3>${date(r.date)}</h3><p>${escape(r.summary)}</p><p class="small-note">${r.addedIds.length} new records · ${r.updatedIds.length} updated records</p></div>`).join(''):'<p>No scheduled review has completed yet.</p>'}</section>`;}
function methodology(){main.innerHTML=heading('Sources & methodology')+demoNote()+`<div class="method-layout"><aside class="method-nav"><a href="#methodology">Approach</a><a href="#coverage">Conversation coverage</a><a href="#methodology-sources">Source register</a><a href="#glossary">Glossary</a></aside><article class="method-body"><section><h2>Scope</h2><p>This watch began with a historical conversation import. Weekly updates now independently research original reports and investigations. It covers incidents, investigations, capability studies, and governance developments. The earlier 2025 research notes remain as background.</p><p>The page summarizes the evidence; it does not assign a reviewed risk rating or a catastrophe probability. Future scenarios and the chat’s subjective probability estimates are not presented as observed events.</p></section><section><h2>Dates and evidence</h2><p>Timeline order follows report or disclosure dates. Where that date is unavailable, the conversation date is labeled explicitly. Each record separately states when the underlying activity occurred, including uncertainty.</p><p>Primary-source reports describe what a developer, government, or researcher reports. They are not independent replication. External research may have uncertain attribution; chat reports preserve claims whose original citations have not been fully rechecked. Failed attempts, successful access, and authorized security research remain distinct.</p><p>Case counts cannot establish prevalence without a denominator and a consistent detection process. Repeated investigations of one incident are follow-ups, not additional intrusions.</p></section><section><h2>Editorial status</h2><p>Historical imports and weekly automated summaries are labeled separately. Source checks are not human editorial approval. The automated process publishes source-supported developments and interpretations without claiming a named human reviewer.</p><p>${data.updates?.enabled?`Weekly reviews are scheduled for ${escape(data.updates.scheduleLabel)}. They assess material incidents, capability changes, and effective safeguards, explaining how the evidence changes the five-year outlook and what would change that assessment next. New records require an accessible original report or investigation; weakly supported candidates are held back.`:'Weekly updates are not enabled yet.'} ${data.updates?.lastCheckedAt?`Last completed source review: ${date(data.updates.lastCheckedAt)}.`:'The first scheduled source review has not run yet.'} Future human-reviewed editions require actual approval metadata.</p></section>${updateHistoryMarkup()}${coverageMarkup()}<section id="methodology-sources"><h2>Source register</h2><p>${data.events.length} records · source dates ${sourceRange()}. Open each record for occurrence dates and evidence limitations.</p>${data.events.map(e=>`<div class="source-record"><button class="text-link" data-event="${e.id}">${escape(e.title)} ↗</button><p class="small-note">${date(e.date)} · ${escape(e.evidence)}</p>${sources(e)}</div>`).join('')}</section><section id="glossary"><h2>Glossary</h2><p>The Simplified vocabulary switch changes timeline summaries. It is off by default.</p><div class="glossary-grid">${Object.keys(glossary).map(t=>`<button data-term="${escape(t)}">${escape(t)} <span>↗</span></button>`).join('')}</div></section></article></div>`;}
const availability = {available:'Available',preview:'Preview',restricted:'Restricted access','open-weights':'Downloadable','existing-users':'Existing users only','product-access':'In company products',retiring:'Retiring',retired:'Retired'};
function currentModels(company){return company.models.filter(model=>model.status!=='retired');}
function modelCard(model,role=''){
 return `<article class="model-card ${role?'featured-model':''}">${role?`<p class="eyebrow">${role}</p>`:''}<div class="model-card-head"><h3>${escape(model.name)}</h3><span class="model-availability ${['restricted','retiring','preview','existing-users'].includes(model.status)?'amber':''}">${availability[model.status]}</span></div><p>${escape(model.purpose)}</p><div class="model-card-foot"><span>${model.releasedAt?`Released ${date(model.releasedAt)}`:escape(model.group)}${model.retirementAt?` · Retires ${date(model.retirementAt)}`:''}</span><a href="${escape(model.sourceUrl)}" target="_blank" rel="noopener noreferrer" aria-label="Official source for ${escape(model.name)}">Source ↗</a></div></article>`;
}
function renderModelCatalog(){
 if(!models)return;
 const company=models.companies.find(c=>c.id===selectedCompany)||models.companies[0];
 selectedCompany=company.id;
 const offerings=currentModels(company), expanded=expandedCompanies.has(company.id);
 document.querySelectorAll('[data-company]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.company===company.id)));
 $('#featured-models').innerHTML=['capable','everyday'].map((key,index)=>modelCard(offerings.find(model=>model.id===company.featured[key]),index?'Everyday use':'Most capable')).join('');
 const toggle=$('#model-expand');
 toggle.setAttribute('aria-expanded',String(expanded));
 toggle.innerHTML=`<span>${expanded?'Hide':'Show'} all ${offerings.length} ${escape(company.name)} models</span><span aria-hidden="true">${expanded?'−':'+'}</span>`;
 $('#model-catalog-note').textContent=company.note;
 $('#company-model-source').href=company.catalogUrl;
 $('#company-model-source').textContent=`${company.name} catalog ↗`;
 $('#company-model-date').textContent=`Checked ${date(company.checkedAt)}`;
 const catalog=$('#model-catalog');catalog.hidden=!expanded;
 catalog.innerHTML=expanded?[...new Set(offerings.map(model=>model.group))].map(group=>`<section class="model-group"><h3>${escape(group)}</h3><div class="model-grid">${offerings.filter(model=>model.group===group).map(model=>modelCard(model)).join('')}</div></section>`).join(''):'';
 $('#model-status').textContent=`${company.name}: ${offerings.length} models. Full catalog ${expanded?'expanded':'collapsed'}.`;
}
function renderIncident(){
 const incident=data.events.find(event=>event.id===selectedIncident);if(!incident)return;
 document.querySelectorAll('[data-incident]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.incident===incident.id)));
 $('#incident-spotlight').innerHTML=`<div class="spotlight-top"><span class="eyebrow">${escape(incident.evidence)}</span><span class="small-note">Reported ${date(incident.date)}</span></div><h3>${escape(incident.title)}</h3><dl class="incident-facts"><div><dt>Observed</dt><dd>${rich(incident.summary_beginner)}</dd></div><div><dt>Implication</dt><dd>${rich(incident.why_it_matters)}</dd></div><div><dt>Evidence limits</dt><dd>${rich(incident.what_it_doesnt_mean)}</dd></div></dl><div class="spotlight-footer"><button class="text-link" data-event="${incident.id}">Read incident & sources ↗</button><span class="small-note">${incident.review.status==='imported'?'Imported record':'Automated source summary'}</span></div>`;
}
function dashboard(){
 const incidents=['hugging-face','dns-escape','medicare'].map(id=>data.events.find(e=>e.id===id)).filter(Boolean);
 const recent=data.events.slice(0,3);
 const safety=data.events.find(e=>e.direction==='improving'&&['primary','research'].includes(e.verification));
 main.innerHTML=`<div class="landscape-status"><span><span class="monitor-mark" aria-hidden="true"></span>Weekly monitoring</span><span>${escape(data.updates.scheduleLabel)} · Incident coverage ${date(data.asOf)}</span></div><section class="landscape-models" aria-labelledby="landscape-title"><div class="landscape-heading"><div><p class="eyebrow">AI landscape</p><h1 id="landscape-title">Current AI models</h1></div><span class="small-note">${models?`Model catalog checked ${date(models.checkedAt)}`:'Model catalog unavailable'}</span></div>${models?`<div class="company-picker" role="group" aria-label="Choose an AI company">${models.companies.map(company=>`<button class="company-choice" data-company="${company.id}" aria-pressed="${selectedCompany===company.id}" aria-controls="company-models"><strong>${escape(company.name)}</strong><span>${escape(company.family)}</span><span class="company-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><div id="company-models"><div id="featured-models" class="featured-models"></div><button id="model-expand" class="model-expand" data-action="expand-models" aria-expanded="false" aria-controls="model-catalog"></button><div id="model-catalog" hidden></div><div class="catalog-provenance"><a id="company-model-source" class="text-link" target="_blank" rel="noopener noreferrer"></a><span id="company-model-date" class="small-note"></span></div><p id="model-catalog-note" class="small-note"></p><p id="model-status" class="sr-only" role="status" aria-live="polite"></p></div>`:'<div class="empty-state"><p>The model catalog could not load. The incident records are still available below.</p><button class="text-link" data-action="retry">Retry ↗</button></div>'}</section><section class="dashboard-incidents" aria-labelledby="major-incidents-title"><div class="incident-index"><p class="eyebrow">Major incidents</p><h2 id="major-incidents-title">Agents crossing boundaries</h2><div class="incident-picker" role="group" aria-label="Choose a major incident">${incidents.map((e,index)=>`<button data-incident="${e.id}" aria-pressed="${e.id===selectedIncident}" aria-controls="incident-spotlight"><span class="incident-number">0${index+1}</span><span><strong>${{'hugging-face':'Hugging Face','dns-escape':'Internet restrictions','medicare':'Medicare statistics'}[e.id]}</strong><small>${date(e.date)}</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div><a href="#timeline" class="text-link">All incident records ↗</a></div><article id="incident-spotlight" class="incident-spotlight" aria-live="polite"></article></section><section class="dashboard-bottom" aria-label="More developments"><article><p class="eyebrow">Capabilities</p><h2>Models & agents</h2><p>A model generates answers. An agent combines a model with tools to carry out tasks, sometimes over many steps.</p><a class="text-link" href="#ladder">Explore capabilities ↗</a></article><article><p class="eyebrow">Latest reports</p><h2>Recent developments</h2><div class="dashboard-recent">${recent.map(e=>`<button data-event="${e.id}"><small>${date(e.date)}</small><span>${escape(e.title)}</span></button>`).join('')}</div></article><article><p class="eyebrow">Safety & control</p><h2>Safeguards in practice</h2>${safety?`<p>${rich(safety.summary_beginner)}</p><button class="text-link" data-event="${safety.id}">Read evidence & limits ↗</button>`:'<a class="text-link" href="#overview">View evidence summary ↗</a>'}</article></section>`;
 renderModelCatalog();renderIncident();
}
function timeline(){
 main.innerHTML=timelineMarkup();
 $('#signal-filter').value=signal;$('#year-filter').value=year;filterEvents();
}
function ladder(){main.innerHTML=ladderMarkup();renderStage(selectedStage);}
function route(){
 if(!data)return;
 const hash=location.hash.slice(1)||'dashboard';
 if(hash==='main'){main.focus();return;}
 const isMethod=['methodology','methodology-sources','glossary','coverage'].includes(hash);
 const views={dashboard,overview,timeline,ladder,methodology};
 const view=isMethod?'methodology':Object.hasOwn(views,hash)?hash:'dashboard';
 const labels={dashboard:'Dashboard',overview:'Overview',timeline:'Timeline',ladder:'Concern ladder',methodology:'Methodology'};
 if(dialog.open)dialog.close();
 document.querySelectorAll('nav a').forEach(a=>{
  const active=a.hash===`#${view}`;
  a.classList.toggle('active',active);
  if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');
 });
 main.dataset.view=view;main.setAttribute('aria-label',labels[view]);
 views[view]();document.title=`${labels[view]} — Frontier Signal`;
 requestAnimationFrame(()=>{
  if(isMethod&&hash!=='methodology')document.getElementById(hash)?.scrollIntoView({behavior:'instant'});
  else window.scrollTo({top:0,behavior:'instant'});
 });
}
function setBeginner(value){beginner=value;$('#beginner-toggle').setAttribute('aria-checked',beginner);try{localStorage.setItem('frontier-simplified-vocabulary',String(beginner));}catch{}if($('#event-list'))filterEvents();}
document.addEventListener('click',event=>{
 const b=event.target.closest('button,a');if(!b)return;
 if(b.dataset.event){returnDialog=null;showEvent(b.dataset.event);}
 else if(b.dataset.company){selectedCompany=b.dataset.company;renderModelCatalog();}
 else if(b.dataset.incident){selectedIncident=b.dataset.incident;renderIncident();}
 else if(b.dataset.action==='expand-models'){if(expandedCompanies.has(selectedCompany))expandedCompanies.delete(selectedCompany);else expandedCompanies.add(selectedCompany);renderModelCatalog();}
 else if(b.dataset.worry){returnDialog=null;showEvent(b.dataset.worry,true);}
 else if(b.dataset.pathway){returnDialog=null;showPathway(b.dataset.pathway);}
 else if(b.dataset.term)showTerm(b.dataset.term);
 else if(b.dataset.stage!==undefined)renderStage(Number(b.dataset.stage));
 else if(b.dataset.filter){category=b.dataset.filter;filterEvents();}
 else if(b.dataset.signal){signal=b.dataset.signal;category='All';location.hash='timeline';}
 else if(b.dataset.action==='outlook'){returnDialog=null;showOutlook();}
 else if(b.dataset.action==='back-dialog'){const previous=returnDialog;returnDialog=null;openDialog(previous);}
 else if(b.dataset.action==='reset-filters'){category='All';signal='all';query='';year='all';$('#signal-filter').value=signal;$('#event-search').value='';$('#year-filter').value='all';filterEvents();}
 else if(b.dataset.action==='future-stage'){selectedStage=7;location.hash='ladder';}
 else if(b.dataset.action==='retry')location.reload();
 if(b.hasAttribute('data-close'))dialog.close();
});
$('#beginner-toggle').onclick=()=>setBeginner(!beginner);
$('.close-dialog').onclick=()=>dialog.close();
dialog.addEventListener('close',()=>{returnDialog=null;});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.addEventListener('change',e=>{if(e.target.id==='signal-filter'){signal=e.target.value;filterEvents();}else if(e.target.id==='year-filter'){year=e.target.value;filterEvents();}});
document.addEventListener('input',e=>{if(e.target.id==='event-search'){query=e.target.value;filterEvents();}});
window.addEventListener('hashchange',route);
try {
 const responses=await Promise.all(['signals','glossary'].map(name=>fetch(`./data/${name}.json`)));
 if(responses.some(r=>!r.ok))throw new Error('Research files unavailable');
 [data,glossary]=await Promise.all(responses.map(r=>r.json()));
 try{const response=await fetch('./data/models.json');if(!response.ok)throw new Error('Model catalog unavailable');models=await response.json();}catch(error){console.warn('Model catalog could not load.',error);}
 data.events.sort((a,b)=>b.date.localeCompare(a.date));
 $('#edition-label').textContent=`AI WATCH · ${date(data.asOf)}`;
 setBeginner(beginner);route();
} catch(error) {
 main.innerHTML=`<div class="empty-state"><p class="eyebrow">FRONTIER SIGNAL</p><h1>The research notes couldn’t load.</h1><p>Please check your connection and try again.</p><button class="text-link" data-action="retry">Try again ↗</button></div>`;
 console.error('Frontier Signal could not load its research files.',error);
}
